#!/usr/bin/env python3
"""Flat colour illustrations for 100 Top-3000 nouns that had none, drawn as polygons.

The same polygon data is created as SVGator projects (see `json_for`) — SVGator's static SVG export returns
exactly these polygons, so the card is built here with the project frame. Colours are palette tokens.
Run: python3 Tools/svgator_top3000_1.py   (then svg_lint on the new files, validate_svg_assets.py, swift test)
"""

import json
import math
import sys

from flat_redraw import ASSETS, BINDINGS, FRAME, PALETTE, ROOT

POS = "noun"  # batches drawing another part of speech set this; non-noun plates get a word_<lemma>_<pos>_plate name

