def svg_for(shapes):
    by_hex = {v.lower().lstrip("#"): v for v in PALETTE.values()}
    body = "".join(f'<polygon points="{" ".join(f"{x},{y}" for x, y in pts)}" fill="{by_hex[h]}"/>' for pts, h in shapes)
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 200">{FRAME}{body}</svg>\n'


def json_for(word):
    """SVGator create_project `document` for one word (polygons only)."""
    kids = []
    for i, (pts, h) in enumerate(WORDS[word]):
        rgb = {k: int(h[j:j + 2], 16) for k, j in (("r", 0), ("g", 2), ("b", 4))}
        kids.append({"id": f"p{i}", "type": "polygon", "title": f"Part {i + 1}",
                     "properties": {"shape": {"points": [{"x": x, "y": y} for x, y in pts]},
                                    "fill": {"paint": {"type": "color", "value": {**rgb, "a": 1}}, "opacity": 1}}})
    return {"id": "svg-1", "type": "svg", "properties": {"shape": {"position": {"x": 0, "y": 0}, "size": {"width": 340, "height": 200}}}, "children": kids}


def main():
    catalog = json.loads(BINDINGS.read_text())
    have = {a["assetName"] for a in catalog["assets"]}
    added = []
    for word, shapes in sorted(WORDS.items()):
        name = f"word_{word}_plate" if POS == "noun" else f"word_{word}_{POS}_plate"
        folder = ASSETS / f"{name}.imageset"
        folder.mkdir(exist_ok=True)
        (folder / f"{name}.svg").write_text(svg_for(shapes))
        (folder / "Contents.json").write_text(json.dumps({
            "images": [{"filename": f"{name}.svg", "idiom": "universal"}],
            "info": {"author": "xcode", "version": 1},
            "properties": {"preserves-vector-representation": True},
        }, separators=(",", ":")) + "\n")
        if name in have:
            continue
        catalog["assets"].append({
            "id": f"illustration.{word}.{POS}.plate", "word": word, "lemma": word, "partOfSpeech": POS, "senseId": None,
            "assetName": name, "assetPath": f"Resources/IllustrationsSVG/Words.xcassets/{name}.imageset/{name}.svg",
            "style": "flat_color", "contexts": ["dictionary_entry"], "version": 1, "tags": ["top3000"],
            "altText": f"Illustration of a {word}." if POS == "noun" else f"Illustration of the {POS} {word}.", "isDecorative": False, "notes": "Top 3000; SVGator drawing, templated alt text",
        })
        added.append(name)
    BINDINGS.write_text(json.dumps(catalog, indent=2, ensure_ascii=False) + "\n")
    # No pbxproj inputPaths: the validate phase is alwaysOutOfDate, and thousands of
    # input paths overflow the /bin/sh environment ("Argument list too long").
    print(f"Drew {len(WORDS)} illustrations, added {len(added)} bindings")


if __name__ == "__main__":
    if len(sys.argv) > 2 and sys.argv[1] == "json":
        print(json.dumps(json_for(sys.argv[2]), separators=(",", ":")))
    else:
        main()
